func NewSpecValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (SpecValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing SpecValue Attribute Value",
				"While creating a SpecValue value, a missing attribute value was detected. "+
					"A SpecValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("SpecValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid SpecValue Attribute Type",
				"While creating a SpecValue value, an invalid attribute value was detected. "+
					"A SpecValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("SpecValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("SpecValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra SpecValue Attribute Value",
				"While creating a SpecValue value, an extra attribute value was detected. "+
					"A SpecValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra SpecValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewSpecValueUnknown(), diags
	}

	checksAttribute, ok := attributes["checks"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`checks is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	checksVal, ok := checksAttribute.(basetypes.ObjectValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`checks expected to be basetypes.ObjectValue, was: %T`, checksAttribute))
	}

	edgeLinkTemplatesAttribute, ok := attributes["edge_link_templates"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`edge_link_templates is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	edgeLinkTemplatesVal, ok := edgeLinkTemplatesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`edge_link_templates expected to be basetypes.ListValue, was: %T`, edgeLinkTemplatesAttribute))
	}

	interSwitchLinkTemplatesAttribute, ok := attributes["inter_switch_link_templates"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`inter_switch_link_templates is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	interSwitchLinkTemplatesVal, ok := interSwitchLinkTemplatesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`inter_switch_link_templates expected to be basetypes.ListValue, was: %T`, interSwitchLinkTemplatesAttribute))
	}

	nodeTemplatesAttribute, ok := attributes["node_templates"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`node_templates is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	nodeTemplatesVal, ok := nodeTemplatesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`node_templates expected to be basetypes.ListValue, was: %T`, nodeTemplatesAttribute))
	}

	operationAttribute, ok := attributes["operation"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`operation is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	operationVal, ok := operationAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`operation expected to be basetypes.StringValue, was: %T`, operationAttribute))
	}

	podTemplatesAttribute, ok := attributes["pod_templates"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`pod_templates is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	podTemplatesVal, ok := podTemplatesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`pod_templates expected to be basetypes.ListValue, was: %T`, podTemplatesAttribute))
	}

	podsAttribute, ok := attributes["pods"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`pods is missing from object`)

		return NewSpecValueUnknown(), diags
	}

	podsVal, ok := podsAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`pods expected to be basetypes.ListValue, was: %T`, podsAttribute))
	}

	if diags.HasError() {
		return NewSpecValueUnknown(), diags
	}

	return SpecValue{
		Checks:                   checksVal,
		EdgeLinkTemplates:        edgeLinkTemplatesVal,
		InterSwitchLinkTemplates: interSwitchLinkTemplatesVal,
		NodeTemplates:            nodeTemplatesVal,
		Operation:                operationVal,
		PodTemplates:             podTemplatesVal,
		Pods:                     podsVal,
		state:                    attr.ValueStateKnown,
	}, diags
}

func NewSpecValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) SpecValue {
	object, diags := NewSpecValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewSpecValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t SpecType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewSpecValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewSpecValueUnknown(), nil
	}

	if in.IsNull() {
		return NewSpecValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewSpecValueMust(SpecValue{}.AttributeTypes(ctx), attributes), nil
}

