func (v ChecksValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var promptsVal basetypes.ListValue
	switch {
	case v.Prompts.IsUnknown():
		promptsVal = types.ListUnknown(types.StringType)
	case v.Prompts.IsNull():
		promptsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		promptsVal, d = types.ListValue(types.StringType, v.Prompts.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"dry_run": basetypes.BoolType{},
			"prompts": basetypes.ListType{
				ElemType: types.StringType,
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"dry_run": basetypes.BoolType{},
		"prompts": basetypes.ListType{
			ElemType: types.StringType,
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"dry_run": v.DryRun,
			"prompts": promptsVal,
		})

	return objVal, diags
}

